export const UsageDoc = defineDoc({

// Attribution is committed atomically with the response, not inferred from the latest author after a crash.
const owner = key.startsWith("team:") ? key.split(":")[1] : bucket === "tools" ? (await tx.doc(TeamRunDoc, conversationId)).owner : undefined;
if (owner !== undefined) {
    const ledger = await tx.doc(TeamUsageDoc, conversationId);
    const person = copyJson(ledger.people[owner] ?? { models: {}, tools: {} });
    const prior = Object.hasOwn(person[bucket], key) ? person[bucket][key] : undefined;
    if (prior === undefined) person[bucket] = { ...person[bucket], [key]: copyJson(usage, { omitUndefinedProperties: true }) };
    else addUsage(prior, usage);
    ledger.people[owner] = person;
}
const totals = (await tx.doc(UsageDoc, conversationId))[bucket];
